import fs from "node:fs";
import path from "node:path";
import crypto from "node:crypto";
import zlib from "node:zlib";

const RELEASE = 'MVP Trainer V5 R8.8.4 DSP / EQ Player-Corner Integration';
const files = [{"path":"src/features/music/MusicMiniPlayer.tsx","expectedBefore":"cea761e3f28c87d83bff1341bb8f13747b904a68fbed726e246483c830f16433","desired":"9bfee5295a9abd70bc90dbbb7339426c109a666b9cd7aa982a7973ff15789e16","gzipBase64":""}];

function normalizedHash(text) {
  const normalized = text.replace(/\r\n/g, "\n").replace(/\r/g, "\n");
  return crypto.createHash("sha256").update(normalized, "utf8").digest("hex");
}
function stamp() {
  const d = new Date();
  const pad = (v) => String(v).padStart(2, "0");
  return `${d.getFullYear()}${pad(d.getMonth()+1)}${pad(d.getDate())}-${pad(d.getHours())}${pad(d.getMinutes())}${pad(d.getSeconds())}`;
}

const repoRoot = process.cwd();
console.log(`\n${RELEASE}`);
console.log(`Repo: ${repoRoot}\n`);

for (const item of files) {
  const target = path.join(repoRoot, ...item.path.split("/"));
  if (!fs.existsSync(target)) throw new Error(`Missing ${item.path}. Run this installer from the MVP Trainer repo root.`);

  const current = fs.readFileSync(target, "utf8");
  const currentHash = normalizedHash(current);
  if (currentHash === item.desired) {
    console.log(`ALREADY CURRENT  ${item.path}`);
    continue;
  }
  if (currentHash !== item.expectedBefore) {
    throw new Error(`Safety stop: ${item.path} does not match the R8.8.3 file this update was built from. No changes were written.`);
  }

  const backup = `${target}.bak-r8-8-4-${stamp()}`;
  fs.copyFileSync(target, backup);
  const next = zlib.gunzipSync(Buffer.from(item.gzipBase64, "base64")).toString("utf8");
  fs.writeFileSync(target, next, "utf8");

  if (normalizedHash(fs.readFileSync(target, "utf8")) !== item.desired) {
    fs.copyFileSync(backup, target);
    throw new Error(`Verification failed for ${item.path}. Original restored from backup.`);
  }
  console.log(`UPDATED          ${item.path}`);
  console.log(`BACKUP           ${path.relative(repoRoot, backup)}`);
}

console.log("\nR8.8.4 install complete.");
console.log("Desktop: DSP / EQ is now structurally outside the Playing From wrapper and occupies the true right side of the player's bottom utility row.");
console.log("Playing From remains centered in the middle column.");
console.log("DSP / EQ stays compact at roughly half the visual area of a Like control and keeps the active output-profile icon.");
console.log("Mobile: Playing From remains centered and the compact DSP / EQ launcher stays right-aligned below it.");
console.log("Next: npm run build");
console.log("In GitHub Desktop, leave .bak-r8-8-4-* files unchecked.\n");
